INSERT INTO plant_catalog (scientific_name, common_name_de, plant_group, notes, aggressive_rhizome, aggressive_source, source_kind, source_ref, licence_status) VALUES
  ('Phragmites australis', 'Gewöhnlicher Schilfrohr', 'other', 'Tab. 29 Zeile 2, Gruppe „Helophyten und Hydrophyten“. TP § 1: Helophyt, Prüfpflanze des FLL-Verfahrens zur Rhizomfestigkeit von Gewässerabdichtungen („aggressivster Rhizombildner unter den Helophyten“)', true, 'Tab. 29: Beispiele von Pflanzen mit aggressiven Wurzeln oder Rhizomen (FLL-GAR-2023, § 10.3, printed p. 125) — „Bei Verwendung oder Vorhandensein derartiger Pflanzenarten sind über den Standardaufbau der Abdichtung hinausgehende bauliche Vorkehrungen, z. B. als Rhizom- und Wurzelsperre, zu treffen und besondere Pflegemaßnahmen vorzusehen.“ — FLL-TP-Rhizom-2023 § 1 (printed p. 7): „Basierend auf Voruntersuchungen hat sich Phragmites australis gegenüber Rhizomen anderer Testpflanzen (Cyperus longus, Schoenoplectus lacustris, Zizania caduciflora) als aggressivster Rhizombildner unter den Helophyten herausgestellt.“', 'guideline', 'FLL-GAR-2023 Tab. 29 (printed p. 125); FLL-TP-Rhizom-2023 § 1 (printed p. 7)', 'guideline'),
